// 5micro.net AdSense審査・読み物コンテンツ用の独自記事データ。
// 各記事は子育てエビデンス研究所の論文知見をもとにした独自解説。出典は各記事末尾に明記。

export interface ArticleRef {
  label: string;
  url: string;
}
export interface ArticleSection {
  heading: string;
  body: string[]; // 段落の配列
}
export interface ArticleImage {
  src: string;
  alt: string;
}
/** 記事に関連する用語解説への導線。 */
export interface RelatedTerm {
  slug: string;
  term: string;
}
export interface Article {
  slug: string;
  title: string;
  lead: string;
  /** 投稿日 'YYYY-MM-DD'。記事を最初に公開（投稿）した日付。 */
  posted: string;
  /** 更新日 'YYYY-MM-DD'。内容を最後に編集した日付。 */
  updated: string;
  /** 公開日 'YYYY-MM-DD'。未設定なら常に公開。この日付を過ぎるまで一覧・詳細に表示しない。 */
  publish?: string;
  /** 下書き。true の間は publish 日付に関わらず非公開（公表を保留する）。 */
  draft?: boolean;
  readMin: number;
  heroImage?: ArticleImage;
  sections: ArticleSection[];
  /** 「2児の父として」の一次体験・感想（任意）。段落の配列。執筆・監修者本人の実感を記す。 */
  parentNote?: string[];
  steps: string[];
  references: ArticleRef[];
  /** 記事末尾に表示する関連用語解説（任意）。 */
  relatedTerms?: RelatedTerm[];
}

/** 記事が公開済みか（閲覧者のブラウザの現在日付で判定。再デプロイ不要で日付到来時に自動表示される）。 */
export function isPublished(a: Article, now: Date = new Date()): boolean {
  if (a.draft) return false;
  if (!a.publish) return true;
  const y = now.getFullYear();
  const m = String(now.getMonth() + 1).padStart(2, '0');
  const d = String(now.getDate()).padStart(2, '0');
  return a.publish <= `${y}-${m}-${d}`;
}

