    lead: '「何でもイヤ！」「自分で！」が続くイヤイヤ期。親には手強い時期ですが、研究はこれを困った問題ではなく、自我と自律が育つ大切な節目だと捉えています。なぜ起きるのか、どう関わると楽になるのかを整理しました。',
