          '気持ちを言葉にして受け止める（「まだ遊びたかったね」）。感情を否定しないことで、こじれにくくなります。さらに、切り替えを前もって予告する（「あと3回すべったら帰ろう」）と、抵抗がやわらぎます。',
          'ただし、危険なことや人を傷つけることには、一貫して線を引きます。気持ちは受け止め、行動には線を引く——この組み合わせが大切です。',
