      'これは子ども相手だけの話ではないと思います。映画「マトリックス・リローデッド」（2003年）には、機械側の設計者が「選択肢を与えれば、人間のほぼ全員が仮想世界を受け入れた」と語る場面があります。SF映画の機械ですら見抜いていた「人は自分で選ぶと納得する」という性質を、心理学は自己決定理論として研究してきたわけです。イヤイヤ期の「どっちにする？」作戦は、その、いちばん小さくてかわいい応用例なのかもしれません。',
