          'つまり乳幼児期は、画面の中の情報を現実の世界に結びつけて理解する力がまだ育ちきっていません。だからこそ、画面を見せること自体よりも、その時間に本来あったはずの「大人との応答的なやり取り」が減ってしまうことのほうが、発達の観点では気がかりだと考えられています。',
