    lead: 'からだの安全教育は、子どもをこわがらせるためのものではありません。Walsh らの2015年コクランレビューは、学校での予防教育が子どもの知識と「自分を守る行動」を高めることを示しています。プライベートゾーンの考え方、体の部位を正しい名前で呼ぶこと、「いやと言う・逃げる・話す」を、落ち着いた言葉で家庭に取り入れる方法を整理します。',
