          'ただしレビューは、被害そのものを減らせたかという長期的な効果までは十分に確かめられていないことも率直に述べています。学校での学びは出発点であり、家庭での日常的な声かけと組み合わさってはじめて力を発揮する、と受けとめるのが現実的です。'
