    lead: '父親が育児に関わることは、子どもの育ちに本当に差を生むのでしょうか。生後3か月の父子のやりとりを家庭でビデオ観察し、その後の行動や発達を追いかけた研究、縦断研究24本をまとめたレビュー、そして父親特有の「取っ組み合いの遊び」に注目した研究まで。日本の父親の育休取得率や家事育児時間の数字も交えながら、「時間の長さ」より大事なものは何かを整理します。',
