          '結果は、生後3か月の時点で「関わりが乏しい（disengaged）」と評定された父親の子どもは、1歳時点で行動の問題が現れるリスクが高いというものでした。統計的に調整したオッズ比は、関わりの乏しさで5.33、よそよそしさ（remote）で3.32。しかもこの関連は、母親の感受性を考慮したあとでも残りました。関連は男の子でやや強い傾向がありました。',
