          'そして、父子の遊びが多い・質が高いことは、子どもの社会情動面の発達や自己制御と関連していました。なぜかについては、こんな仮説が語られています。取っ組み合いの遊びは、興奮をぐっと高めて、行き過ぎる前に収める、という往復を繰り返します。この「上げて、下げる」の反復が、感情のコントロールを安全に練習する場になっているのではないか、というものです。',
