          'この知見は、父親を責めるためのものではありません。むしろ逆で、「関われていない父親」を叱咤するより、その人自身が支援の対象になりうる、ということを示しています。眠れない、何をしても楽しくない、といった状態が2週間以上続くなら、それは意志の問題ではなく相談すべきサインです。',
