    lead: '子どもを叱ったあとで「あんなに怒らなくてもよかったのに」と落ち込む。多くの親が経験することです。怒りの扱い方については「6秒待つ」「発散してすっきりする」といった俗説がよく知られていますが、研究の裏づけがあるものと、そうでないものが混ざっています。怒りが強くなる条件は何か、どんな鎮め方に効果が確認されているのか、そして親自身の消耗（ペアレンタル・バーンアウト）が子どもへの怒りにどうつながるのかを、実験研究とメタ分析から整理します。',
