          '結果は、カタルシス説の予想と逆でした。相手のことを考えながら叩いた群がいちばん怒りが強く、そのあとに与えられた「相手に大音量の騒音を浴びせる機会」でも最も攻撃的でした。次に攻撃的だったのは体を鍛えることを考えながら叩いた群で、何もしなかった群がいちばん穏やかでした。つまり「何もしない」ことが、発散するより効いたのです。怒りを反芻しながら体を動かすと、怒りは薄まるどころか濃くなる、と読めます。',
